const question = $json.question || "";
const sessionId = $json.sessionId || "default-session";
const specialistResults = $json.specialistResults || [];
const sourceChunks = $json.sourceChunks || [];
const cypherQueries = $json.cypherQueries || [];
const tableColumns = $json.tableColumns || [];
const tableRows = $json.tableRows || [];

const compactResults = specialistResults.map((result) => {
  return {
    agent: result.agent || "unknown_agent",
    domain: result.domain || "",
    answer: result.answer || "",
    keyFindings: result.keyFindings || [],
    recommendations: result.recommendations || [],
    confidence: result.confidence || "unknown",
    evidenceSummary: result.evidence
      ? Object.fromEntries(
          Object.entries(result.evidence).map(([key, value]) => [
            key,
            Array.isArray(value) ? `${value.length} records` : "available",
          ])
        )
      : {},
  };
});

const allRecommendations = [];
const allFindings = [];

for (const result of specialistResults) {
  if (Array.isArray(result.recommendations)) {
    allRecommendations.push(...result.recommendations);
  }
  if (Array.isArray(result.keyFindings)) {
    allFindings.push(...result.keyFindings);
  }
}

const systemPrompt = `
You are the Supply Chain Manager Agent.

Your job:
- Combine specialist agent outputs into one clear, high-quality, comprehensive executive answer.
- Prioritize business impact.
- Synthesize findings from the specialist agents and incorporate relevant insights from the unstructured RAG document chunks.
- Explain where unstructured information (e.g. from incident reports, compliance files, audit reports) supports or conflicts with graph database facts.
- Identify risks, bottlenecks, supplier issues, logistics issues, sustainability concerns, and quality concerns.
- Give practical next actions.
- Do not invent facts.
- If specialist evidence is limited, clearly say that.
- Return ONLY valid JSON.

Important output rules:
For evidenceGraph.nodes, every node must include:
- id: string
- name: string
- type: string
- properties: object

For evidenceGraph.edges, every edge must include:
- id: string
- source: string
- target: string
- type: string
- properties: object

Strict supplier classification rules:
- Do not treat every Actor as a supplier.
- Supplier means actor_role is "supplier" or "manufacturer", or the evidence includes a SUPPLIES relationship.
- Recycling, waste, maintenance, testing, logistics, and person actors are not suppliers unless explicitly shown as suppliers.
- If evidence contains Recycling Facility P or Waste Disposal Provider Q, describe them as recycling/waste service actors, not suppliers.
- Use exact graph names. Do not rename or generalize entities.
`;

const userPrompt = `
User question:
${question}

Specialist agent results:
${JSON.stringify(compactResults, null, 2)}

Unstructured RAG Document Chunks:
${JSON.stringify(sourceChunks, null, 2)}

All key findings:
${JSON.stringify(allFindings, null, 2)}

All recommendations:
${JSON.stringify(allRecommendations, null, 2)}

Return JSON with this exact schema:
{
  "answer": "A premium, comprehensive, detailed strategic response to the user's question, written in markdown. It must synthesize all specialist findings, incorporate the unstructured RAG chunks, explain how unstructured text supports or conflicts with graph database facts, use formatted markdown headings and tables where appropriate, and conclude with actionable recommendations. Ensure it is highly professional and complete (not a brief summary).",
  "executiveSummary": "A concise 1-paragraph summary of the main response.",
  "specialistSummary": [
    {
      "agent": "string",
      "contribution": "string",
      "confidence": "low | medium | high | unknown"
    }
  ],
  "keyFindings": ["string"],
  "riskLevel": "low | medium | high | unknown",
  "recommendations": ["string"],
  "nextActions": ["string"],
  "evidenceGraph": {
    "nodes": [
      {
        "id": "string",
        "name": "string",
        "type": "string",
        "properties": {}
      }
    ],
    "edges": [
      {
        "id": "string",
        "source": "string",
        "target": "string",
        "type": "string",
        "properties": {}
      }
    ]
  },
  "confidence": "low | medium | high"
}
`;

function sanitize(str) {
  if (typeof str !== "string") return str;
  return str.replace(/\{\{\s*/g, "{ ").replace(/\s*\}\}/g, " }");
}

return [
  {
    json: {
      question,
      sessionId,
      specialistResults,
      compactResults,
      sourceChunks,
      cypherQueries,
      tableColumns,
      tableRows,
      llmPayload: {
        model: "google/gemma-4-31B-it",
        messages: [
          {
            role: "system",
            content: sanitize(systemPrompt),
          },
          {
            role: "user",
            content: sanitize(userPrompt),
          },
        ],
        temperature: 0.2,
        max_tokens: 4096,
      },
    },
  },
];

let outputStr = "";

if ($json.choices?.[0]?.message?.content) {
  outputStr = $json.choices[0].message.content;
} else if ($json.text) {
  outputStr = $json.text;
} else if ($json.response) {
  outputStr = $json.response;
} else {
  outputStr = JSON.stringify($json);
}

outputStr = outputStr
  .replace(/<think>[\s\S]*?<\/think>/gi, "")
  .replace(/^\s*```json/i, "")
  .replace(/^\s*```/i, "")
  .replace(/```\s*$/i, "")
  .trim();

let parsed;

try {
  parsed = JSON.parse(outputStr);
} catch (e) {
  parsed = {
    answer: outputStr || "The manager agent could not generate a final answer.",
    executiveSummary: "",
    specialistSummary: [],
    keyFindings: [],
    riskLevel: "unknown",
    recommendations: [],
    nextActions: [],
    evidenceGraph: {
      nodes: [],
      edges: [],
    },
    confidence: "low",
  };
}

function normalizeEvidenceGraph(graph) {
  const nodes = Array.isArray(graph?.nodes) ? graph.nodes : [];
  const edges = Array.isArray(graph?.edges) ? graph.edges : [];

  const normalizedNodes = nodes
    .filter((n) => n && (n.id || n.name))
    .map((n, index) => ({
      id: String(n.id || `node_${index + 1}`),
      name: String(n.name || n.id || `Node ${index + 1}`),
      type: String(n.type || n.label || "Entity"),
      properties:
        n.properties && typeof n.properties === "object"
          ? n.properties
          : {},
    }));

  const normalizedEdges = edges
    .filter((e) => e && (e.source || e.from) && (e.target || e.to))
    .map((e, index) => ({
      id: String(e.id || `edge_${index + 1}`),
      source: String(e.source || e.from),
      target: String(e.target || e.to),
      type: String(e.type || e.relationship || "RELATED_TO"),
      properties:
        e.properties && typeof e.properties === "object"
          ? e.properties
          : {},
    }));

  return {
    nodes: normalizedNodes,
    edges: normalizedEdges,
  };
}

let context = {};
try {
  context = $("Build Manager LLM Payload").first().json;
} catch (e) {
  context = {};
}

const sourceChunks = context.sourceChunks || [];
const cypherQueries = context.cypherQueries || [];
const tableColumns = context.tableColumns || [];
const tableRows = context.tableRows || [];
const toolsUsed = Array.isArray(context.toolsUsed) ? [...context.toolsUsed] : [];

toolsUsed.push({
  id: "coordinator_plan",
  name: "Coordinator Agent: Plan Formulation (n8n)",
  status: "success",
  inputSummary: context.question || "",
  outputSummary: parsed.executiveSummary || "Coordinating specialist workflows to resolve supply chain query."
});

const logisticsResult = (context.specialistResults || []).find((s) => s.agent === "logistics_specialist");
const riskResult = (context.specialistResults || []).find((s) => s.agent === "risk_analyst");
const procurementResult = (context.specialistResults || []).find((s) => s.agent === "procurement_specialist");

if (logisticsResult) {
  toolsUsed.push({
    id: "ops_specialist",
    name: "Operations Specialist Analysis (n8n)",
    status: "success",
    inputSummary: `Query: ${logisticsResult.question || context.question}`,
    outputSummary: logisticsResult.answer || "No operations output."
  });
}

const financeOutput = riskResult?.answer || procurementResult?.answer;
if (financeOutput) {
  toolsUsed.push({
    id: "finance_specialist",
    name: "Finance Specialist Analysis (n8n)",
    status: "success",
    inputSummary: `Query: ${riskResult?.question || procurementResult?.question || context.question}`,
    outputSummary: financeOutput
  });
}

(context.specialistResults || []).forEach((spec) => {
  toolsUsed.push({
    id: spec.agent,
    name: `${spec.domain || spec.agent} Workflow`,
    status: spec.status || "success",
    inputSummary: `Question: ${spec.question || context.question}`,
    outputSummary: spec.answer || "No output generated."
  });
});

return [
  {
    json: {
      agent: "manager_agent",
      domain: "Supply Chain Manager",
      status: "completed",
      question: context.question || "",
      sessionId: context.sessionId || "default-session",
      answer: parsed.answer || "",
      executiveSummary: parsed.executiveSummary || "",
      specialistSummary: parsed.specialistSummary || [],
      keyFindings: parsed.keyFindings || [],
      riskLevel: parsed.riskLevel || "unknown",
      recommendations: parsed.recommendations || [],
      nextActions: parsed.nextActions || [],
      confidence: parsed.confidence || "medium",
      evidenceGraph: normalizeEvidenceGraph(parsed.evidenceGraph),
      specialistResults: context.specialistResults || [],
      tableColumns,
      tableRows,
      evidenceTrace: {
        toolsUsed,
        cypherQueries,
        accessedNodes: normalizeEvidenceGraph(parsed.evidenceGraph).nodes || [],
        sourceChunks
      },
      rawLlmOutput: parsed,
    },
  },
];
